    /**
     * Creates a Text Art object with the parameters specified.
     *
     * @param oTextPr - The text properties.
     * @param sText - The text for the Text Art object.
     * @param sTransform - Text transform type.
     * @param oFill - The color or pattern used to fill the Text Art object.
     * @param oStroke - The stroke used to create the Text Art object shadow.
     * @param nRotAngle - Rotation angle.
     * @param nWidth - The Text Art width measured in English measure units.
     * @param nHeight - The Text Art heigth measured in English measure units.
     * @param nIndLeft - The Text Art left side indentation value measured in English measure units.
     * @param nIndTop - The Text Art top side indentation value measured in English measure units.
     * @default oTextPr = Api.CreateTextPr()
     * @default sText = "Your text here"
     * @default sTransform = "textNoShape"
     * @default oFill = Api.CreateNoFill()
     * @default oStroke = Api.CreateStroke(0, Api.CreateNoFill())
     * @default nRotAngle = 0
     * @default nWidth = 1828800
     * @default nHeight = 1828800
     * @default nIndLeft = ApiPresentation.GetWidth() / 2
     * @default nIndTop = ApiPresentation.GetHeight() / 2
     *
     * @example
     * ```js
     * // How do I add decorative curved text to a presentation in a presentation?
     *
     * // Insert text art with custom formatting and text effects in a presentation.
     *
     * const presentation = Api.GetPresentation();
     * const slide = presentation.GetSlideByIndex(0);
     * slide.RemoveAllObjects();
     *
     * const run = Api.CreateRun();
     * const textPr = run.GetTextPr();
     * textPr.SetFontSize(72);
     * textPr.SetBold(true);
     * textPr.SetCaps(true);
     * textPr.SetColor(Api.HexColor('#333333'));
     * textPr.SetFontFamily("Comic Sans MS");
     * const fill = Api.CreateSolidFill(Api.RGB(255, 111, 61));
     * const stroke = Api.CreateStroke(1 * 36000, Api.CreateSolidFill(Api.RGB(51, 51, 51)));
     * const textArt = Api.CreateWordArt(textPr, "onlyoffice", "textArchUp", fill, stroke, 0, 100 * 36000, 30 * 36000);
     * slide.AddObject(textArt);
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/presentation-api/Api/Methods/CreateWordArt/
     */
    CreateWordArt(oTextPr?: ApiTextPr, sText?: string, sTransform?: TextTransform, oFill?: ApiFill, oStroke?: ApiStroke, nRotAngle?: number, nWidth?: EMU, nHeight?: EMU, nIndLeft?: EMU, nIndTop?: EMU): ApiDrawing;

    /**
     * Converts English Metric Units (EMUs) to millimeters.
     *
     * @param emu - The value in English Metric Units (EMUs).
     * @returns The value in millimeters.
     *
     * @example
     * ```js
     * // How can I convert between emus and millimeters for object sizing in a presentation?
     *
     * // Transform measurement values to display size equivalents in a presentation.
     *
     * const emus = 780000;
     * const millimeters = Api.EmusToMillimeters(emus);
     *
     * const rgb = Api.CreateRGBColor(50, 150, 250);
     * const fill = Api.CreateSolidFill(rgb);
     * const stroke = Api.CreateStroke(0, Api.CreateNoFill());
     * const shape = Api.CreateShape('rect', 300 * 36000, 150 * 36000, fill, stroke);
     * const paragraph = shape.GetContent().GetElement(0);
     * paragraph.AddText(emus + ' emus are equal to ' + millimeters + ' millimeters.');
     *
     * const presentation = Api.GetPresentation();
     * const slide = presentation.GetSlideByIndex(0);
     * slide.RemoveAllObjects();
     * slide.AddObject(shape);
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/presentation-api/Api/Methods/EmusToMillimeters/
     */
